    const n = big ? 30000 : r.int(1, 9);
    const label = r.shuffle([...Array(n).keys()]);
    const edges = [];
    for (let i = 1; i < n; i++) {
      // big trees are long and stringy, so naive recursion runs out of stack
      const p = big ? (r.bool(0.7) ? i - 1 : r.int(Math.max(0, i - 5), i - 1)) : r.int(0, i - 1);
      edges.push(r.bool() ? [label[i], label[p]] : [label[p], label[i]]);
    }
    return [n, r.shuffle(edges)];
  }

