function distanceTotals(n: number, edges: number[][]): number[] {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
  const parent = new Array(n).fill(-1), depth = new Array(n).fill(0);
  const order = [0];
  const seen = new Array(n).fill(false);
  seen[0] = true;
  for (let h = 0; h < order.length; h++) {
    const u = order[h];
    for (const v of adj[u]) if (!seen[v]) {
      seen[v] = true; parent[v] = u; depth[v] = depth[u] + 1; order.push(v);
    }
  }
  const size = new Array(n).fill(1);
  for (let i = n - 1; i > 0; i--) size[parent[order[i]]] += size[order[i]];
  const totals = new Array(n).fill(0);
  totals[0] = depth.reduce((s, d) => s + d, 0);
  for (let i = 1; i < n; i++) {
    const v = order[i];
    totals[v] = totals[parent[v]] + n - 2 * size[v];
  }
  return totals;
}

